     */
    suspend fun `callOnSelectorAll`(`selector`: kotlin.String, `expression`: kotlin.String): kotlin.String
    
    /**
     * Like [`Page::call_json`] but coerces the result to a string.
     */
    suspend fun `callString`(`function`: kotlin.String, `argsJson`: kotlin.String): kotlin.String
    
    /**
     * Clears the recorded intercepted requests.
     */
    suspend fun `clearRequests`()
    
    /**
     * Moves the mouse to (x, y) and performs a click (down & up) with human-like delays.
     */
    suspend fun `clickMouse`(`x`: kotlin.Double, `y`: kotlin.Double): Page
    
    /**
     * Closes the page.
     */
    suspend fun `closePage`()
    
    /**
     * Returns the full HTML content of the page.
     */
    suspend fun `content`(): kotlin.String
    
    /**
     * Returns a single cookie by name as JSON (or null).
     */
    suspend fun `cookie`(`name`: kotlin.String): kotlin.String
    
    /**
     * Returns the cookies visible to this page as a JSON array.
     */
    suspend fun `cookies`(): kotlin.String
    
    /**
     * Starts CSS coverage collection.
     */
    suspend fun `coverageStartCss`()
    
    /**
     * Starts JS coverage collection.
     */
    suspend fun `coverageStartJs`()
    
    /**
     * Stops CSS coverage collection and returns the result as JSON.
     */
