    /**
     * Stops JS coverage collection and returns the result as JSON.
     */
    suspend fun `coverageStopJs`(): kotlin.String
    
    /**
     * Returns the page PDF as a base64 string.
     */
    suspend fun `createPdfStream`(): kotlin.String
    
    fun `decodeBase64`(`data`: kotlin.String): kotlin.ByteArray
    
    /**
     * Overrides the idle state.
     */
    suspend fun `emulateIdleState`(`isUserActive`: kotlin.Boolean, `isScreenUnlocked`: kotlin.Boolean)
    
    /**
     * Emulates a media type and/or colour scheme.
     */
    suspend fun `emulateMedia`(`media`: kotlin.String?, `colorScheme`: kotlin.String?)
    
    suspend fun `ensureInterception`()
    
    /**
     * Evaluates JavaScript and coerces the result to a bool.
     */
    suspend fun `evaluateBool`(`expression`: kotlin.String): kotlin.Boolean
    
    /**
     * Evaluates JavaScript and returns the resulting object as an [`Element`].
     */
    suspend fun `evaluateHandle`(`expression`: kotlin.String): Element
    
    /**
     * Evaluates JavaScript in the page and returns the result as a JSON string.
     */
    suspend fun `evaluateJson`(`expression`: kotlin.String): kotlin.String
    
    /**
     * Evaluates JavaScript and coerces the result to a string.
     */
    suspend fun `evaluateString`(`expression`: kotlin.String): kotlin.String
    
    /**
     * Returns the registered event names.
     */
    suspend fun `eventNames`(): List<kotlin.String>
    
    /**
