    /**
     * Starts CDP tracing on this page's session.
     */
    suspend fun `startTracing`()
    
    /**
     * Stops the screencast.
     */
    suspend fun `stopScreencast`()
    
    /**
     * Stops CDP tracing on this page's session.
     */
    suspend fun `stopTracing`()
    
    /**
     * Returns cookies + localStorage as a storage-state JSON object.
     */
    suspend fun `storageState`(): kotlin.String
    
    /**
     * The CDP target id backing this page.
     */
    fun `targetId`(): kotlin.String
    
    /**
     * Returns the page title.
     */
    suspend fun `title`(): kotlin.String
    
    /**
     * Dispatches a touch tap at (x, y).
     */
    suspend fun `touchTap`(`x`: kotlin.Double, `y`: kotlin.Double)
    
    /**
     * Removes the routes registered for `pattern`.
     */
    suspend fun `unroute`(`pattern`: kotlin.String)
    
    /**
     * Removes every route rule.
     */
    suspend fun `unrouteAll`()
    
    /**
     * Returns the current document URL.
     */
    suspend fun `url`(): kotlin.String
    
    /**
     * Waits for the next CDP event named `event_name` and returns its params.
     *
     * The relevant domain is enabled first (best effort), so callers do not
     * have to.
     */
    suspend fun `waitForEvent`(`eventName`: kotlin.String, `timeoutMs`: kotlin.ULong): kotlin.String
    
    /**
     * [`Page::wait_for_event`] with the default 30s timeout.
     */
    suspend fun `waitForEventDefault`(`eventName`: kotlin.String): kotlin.String
    
    /**
     * Polls `expression` until it evaluates truthy or `timeout_ms` elapses.
     */
    suspend fun `waitForFunction`(`expression`: kotlin.String, `timeoutMs`: kotlin.ULong)
    
    /**
     * Waits for the page to finish loading.
     */
    suspend fun `waitForNavigation`()
    
    /**
     * Waits for an element matching the selector to appear in the DOM.
     */
    suspend fun `waitForSelector`(`selector`: kotlin.String): Element
    
    /**
     * Waits for the first XPath match to appear.
     */
    suspend fun `waitForXpath`(`xpath`: kotlin.String, `timeoutMs`: kotlin.ULong): Element
    
    suspend fun `windowId`(): kotlin.Long
    
    /**
     * Returns the window position as JSON (`{x,y}`).
     */
    suspend fun `windowPosition`(): kotlin.String
    
    /**
     * Returns the window bounds as JSON (`{left,top,width,height,windowState}`).
     */
    suspend fun `windowRect`(): kotlin.String
    
    /**
     * Returns the window size as JSON (`{width,height}`).
     */
    suspend fun `windowSize`(): kotlin.String
    
    companion object
}

open class Page: Disposable, AutoCloseable, PageInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_xcelerate_fn_free_page(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_xcelerate_fn_clone_page(handle, status)
        }
    }

    
    /**
     * Activates this page's target.
     */
    @Throws(XcelerateException::class)
