/**
 * Configuration for the Browser instance.
 */
data class BrowserConfig (
    /**
     * Whether to run the browser in headless mode.
     */
    var `headless`: kotlin.Boolean = true
    , 
    /**
     * Deprecated: enable the first-party `stealth` plugin. Prefer `plugins`.
     *
     * This is sugar for adding `"stealth"` to [`BrowserConfig::plugins`] and
     * will be removed in a future major release.
     */
    var `stealth`: kotlin.Boolean = false
    , 
    /**
     * Whether to run the browser as a detached process.
     */
    var `detached`: kotlin.Boolean = true
    , 
    /**
     * Optional path to the browser executable.
     */
    var `executablePath`: kotlin.String? = null
    , 
    /**
     * First-party plugins to enable for this browser (for example
     * `["stealth"]`). Default-deny: no plugin does anything unless listed
     * here (or enabled afterwards with `Browser::use_plugin`).
     */
    var `plugins`: List<kotlin.String>? = null
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBrowserConfig: FfiConverterRustBuffer<BrowserConfig> {
    override fun read(buf: ByteBuffer): BrowserConfig {
        return BrowserConfig(
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalSequenceString.read(buf),
        )
    }

    override fun allocationSize(value: BrowserConfig) = (
            FfiConverterBoolean.allocationSize(value.`headless`) +
            FfiConverterBoolean.allocationSize(value.`stealth`) +
            FfiConverterBoolean.allocationSize(value.`detached`) +
            FfiConverterOptionalString.allocationSize(value.`executablePath`) +
            FfiConverterOptionalSequenceString.allocationSize(value.`plugins`)
    )

    override fun write(value: BrowserConfig, buf: ByteBuffer) {
            FfiConverterBoolean.write(value.`headless`, buf)
            FfiConverterBoolean.write(value.`stealth`, buf)
            FfiConverterBoolean.write(value.`detached`, buf)
            FfiConverterOptionalString.write(value.`executablePath`, buf)
            FfiConverterOptionalSequenceString.write(value.`plugins`, buf)
    }
}





sealed class XcelerateException(message: String): kotlin.Exception(message) {
        
        class WsException(message: String) : XcelerateException(message)
        
        class SerdeException(message: String) : XcelerateException(message)
        
        class CdpResponseException(message: String) : XcelerateException(message)
        
        class HttpException(message: String) : XcelerateException(message)
        
        class NotFound(message: String) : XcelerateException(message)
        
        class InternalException(message: String) : XcelerateException(message)
        
        class Unsupported(message: String) : XcelerateException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<XcelerateException> {
        override fun lift(error_buf: RustBuffer.ByValue): XcelerateException = FfiConverterTypeXcelerateError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeXcelerateError : FfiConverterRustBuffer<XcelerateException> {
    override fun read(buf: ByteBuffer): XcelerateException {
        
            return when(buf.getInt()) {
            1 -> XcelerateException.WsException(FfiConverterString.read(buf))
            2 -> XcelerateException.SerdeException(FfiConverterString.read(buf))
            3 -> XcelerateException.CdpResponseException(FfiConverterString.read(buf))
            4 -> XcelerateException.HttpException(FfiConverterString.read(buf))
            5 -> XcelerateException.NotFound(FfiConverterString.read(buf))
            6 -> XcelerateException.InternalException(FfiConverterString.read(buf))
            7 -> XcelerateException.Unsupported(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: XcelerateException): ULong {
        return 4UL
    }

    override fun write(value: XcelerateException, buf: ByteBuffer) {
        when(value) {
            is XcelerateException.WsException -> {
                buf.putInt(1)
                Unit
            }
            is XcelerateException.SerdeException -> {
                buf.putInt(2)
                Unit
            }
            is XcelerateException.CdpResponseException -> {
                buf.putInt(3)
                Unit
            }
            is XcelerateException.HttpException -> {
                buf.putInt(4)
                Unit
            }
            is XcelerateException.NotFound -> {
                buf.putInt(5)
                Unit
            }
            is XcelerateException.InternalException -> {
                buf.putInt(6)
                Unit
            }
            is XcelerateException.Unsupported -> {
                buf.putInt(7)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterOptionalSequenceString: FfiConverterRustBuffer<List<kotlin.String>?> {
    override fun read(buf: ByteBuffer): List<kotlin.String>? {
